cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote", () => {
  // Edge case: nothing to insure
  it.todo("empty item list → premium 5 G (only the processing fee)");

  // Base premiums per main item type (+ 5 G fee, no other modifiers)
  it.todo("sword (steel, enchantment 3, not cursed) → premium 105 G (100 base + 5 fee)");
  it.todo("amulet → premium 65 G (60 base + 5 fee)");
  it.todo("staff → premium 85 G (80 base + 5 fee)");
  it.todo("potion → premium 45 G (40 base + 5 fee)");

  // Components and the building block of 3 alike components
  it.todo("1 rune → base premium 25 G");
  it.todo("2 runes → base premium 50 G");
  it.todo("3 runes → base premium 60 G (block applies)");
  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
  it.todo("7 runes → base premium 175 G");
  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");

  // Item-specific modifiers
  it.todo("cursed sword adds 50 % risk surcharge to that item's base premium");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");

  // Policy-wide modifiers
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("each contract after the customer's first gets a 15 % follow-up discount");
  it.todo("first insurance surcharge still applies on a follow-up contract (each quote's items are a first insurance)");

  // Modifier scope on multi-item policies
  it.todo("cursed sword + plain amulet → cursed surcharge is 50 G (50 % of the cursed item only), 210 G before further modifiers and fee");

  // Rounding in MHPCO's favour
  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // Integration examples
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 → premium 160 G");

  // Errors
  it.todo("quote with an unknown item type (broomstick) → error, non-zero exit, no results");
});

describe("MHPCO Claim Office — claim", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("rune damaged 200 G → payout 100 G (no enchantment level or material, no special clause)");

  // Special clauses
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");

  // Deductible per damage event
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // Insurance sum and cap
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium with modifiers 165 G) → cap 2000 G (unmodified insurance value)");
  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");

  // Cap exhaustion across successive claims
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // Payout rounding in MHPCO's favour
  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // Multiple items of the same type
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries against two insured swords → each entry gets its own deductible");
  it.todo("more damage entries of a type than the policy covers → error, non-zero exit");

  // Errors
  it.todo("claim damage for an item not part of the policy (amulet when only a sword is insured) → error, non-zero exit");
  it.todo("claim damage with an unknown item type → error, non-zero exit");
  it.todo("claim damage with amount: -200 → error, non-zero exit");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("processes steps sequentially, a claim referring to its quote by zero-based policy index");
  it.todo("on an invalid scenario exits non-zero and writes an error description to stderr");
});
EOF
