cat > src/claim-office.ts <<'EOF'
const PROCESSING_FEE = 5;

const SWORD_BASE_PREMIUM = 100;

type Item = { type: string };

type QuoteStep = { op: "quote"; items: Item[] };

type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };

type Result = { premium: number };

const quote = (step: QuoteStep): Result => ({
  premium: step.items.length * SWORD_BASE_PREMIUM + PROCESSING_FEE,
});

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map(quote),
});
EOF
