content.content:
const PROCESSING_FEE = 5;

type ItemType = "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone";

const BASE_PREMIUM_BY_TYPE: Record<ItemType, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

type Item = {
  type: ItemType;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

type QuoteStep = { op: "quote"; items: Item[] };

type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };

type Result = { premium: number };

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

const COMPONENT_TYPES: ReadonlySet<ItemType> = new Set(["rune"]);

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const isComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => isComponent(item) && item.type === items[0].type);

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

const totalBasePremium = (items: Item[]): number =>
  isComponentBlock(items) ? COMPONENT_BLOCK_BASE_PREMIUM : sumOfBasePremiums(items);

const quote = (items: Item[]): Result => ({
  premium: totalBasePremium(items) + PROCESSING_FEE,
});

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => quote(step.items)),
});

