  COMPONENT_TYPES.has(group.type) && group.items.length === COMPONENT_BLOCK_SIZE;

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

const basePremiumForGroup = (group: SameTypeGroup): number =>
  isComponentBlock(group)
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sumOfBasePremiums(group.items);

const totalBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);

const quote = (items: Item[]): Result => ({
  premium: totalBasePremium(items) + PROCESSING_FEE,
});

