new='''const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

const loyaltyDiscountOn = (basePremium: number, customer: Customer): number =>
  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;

const quote = (items: Item[], customer: Customer): Result => {
  const basePremium = totalBasePremium(items);
  return {
    premium:
      basePremium +
      totalItemSurcharges(items) -
      loyaltyDiscountOn(basePremium, customer) +
      PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => quote(step.items, scenario.customer)),
});'''
