p='src/claim-office.ts'
s=open(p).read()

# insurance values table
s=s.replace('''type Item = {''','''const INSURANCE_VALUE_BY_TYPE: Record<ItemType, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

type Item = {''')

# step / scenario / result types
s=s.replace('''type QuoteStep = { op: "quote"; items: Item[] };

type Customer = { yearsWithMHPCO: number };

type Scenario = { customer: Customer; steps: QuoteStep[] };

type Result = { premium: number };''','''type QuoteStep = { op: "quote"; items: Item[] };

type Damage = { itemType: ItemType; amount: number };

type Incident = { cause: string; damages: Damage[] };

type ClaimStep = { op: "claim"; policy: number; incident: Incident };

type Step = QuoteStep | ClaimStep;

type Customer = { yearsWithMHPCO: number };

type Scenario = { customer: Customer; steps: Step[] };

type QuoteResult = { premium: number };

type ClaimResult = { payout: number; remainingCap: number };

type Result = QuoteResult | ClaimResult;

// A policy created by a quote step, tracked so later claims can draw on its cap.
type Policy = { items: Item[]; remainingCap: number };''')

s=s.replace('): Result => {\n  rejectUninsurableItems(items);','): QuoteResult => {\n  rejectUninsurableItems(items);')

# claim processing + new runScenario
s=s.replace('''// A step is a follow-up contract when the customer already holds one from an
// earlier step of this scenario, so every step but the first.
export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step, index) =>
    quote(step.items, scenario.customer, index > 0),
  ),
});''','''const DEDUCTIBLE_PER_DAMAGE = 100;

const insuranceValueFor = (item: Item): number =>
  INSURANCE_VALUE_BY_TYPE[item.type];

const CAP_MULTIPLE = 2;

const capFor = (items: Item[]): number =>
  CAP_MULTIPLE * sumOverItems(items, insuranceValueFor);

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

// The MHPCO rounds payouts down — always in its own favour.
const roundPayoutInMHPCOsFavour = (payout: number): number =>
  Math.floor(payout);

const claim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = roundPayoutInMHPCOsFavour(
    incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage), 0),
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";

// A step is a follow-up contract when the customer already holds one from an
// earlier step of this scenario, so every quote but the first.
export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const policies = new Map<number, Policy>();
  const results: Result[] = [];

  scenario.steps.forEach((step, index) => {
    if (isQuoteStep(step)) {
      results.push(quote(step.items, scenario.customer, policies.size > 0));
      policies.set(index, {
        items: step.items,
        remainingCap: capFor(step.items),
      });
      return;
    }
    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`No policy was created by step ${step.policy}`);
    }
    results.push(claim(policy, step.incident));
  });

  return { results };
};''')
